    p = Payment("p","i",Decimal("100.00"),created_at=T0)
    try: capture_partial(p,bad,T0)
    except BillingError as e: print("bad amount:", e.code)

# exceeds
p = Payment("p","i",Decimal("100.00"),created_at=T0)
try: capture_partial(p,Decimal("100.01"),T0)
