# invalid state
p = Payment("p","i",Decimal("100.00"),status="captured",created_at=T0)
try: capture_partial(p,Decimal("10"),T0)
except BillingError as e: print("state:", e.code)

# naive
p = Payment("p","i",Decimal("100.00"),created_at=T0)
try: capture_partial(p,Decimal("10"),datetime(2026,1,1))
except BillingError as e: print("naive:", e.code)

# float
p = Payment("p","i",Decimal("100.00"),created_at=T0)
try: capture_partial(p,60.0,T0)
except BillingError as e: print("float:", e.code)
